#!/usr/bin/env node
/**
 * Starts the server pinned to the isolated local demo database
 * (see .env.demo, generated by asking dev — same Atlas cluster, separate
 * `bnn_demo` database) instead of whatever MONGO_URI the regular .env
 * points to. dotenv never overwrites an already-set env var, so loading
 * .env.demo FIRST here means src/index.js's own `dotenv.config()` call
 * fills in every other variable (JWT_SECRET, API keys, etc.) from the
 * regular .env without touching MONGO_URI.
 */

const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env.demo'), quiet: true });
require('../src/index.js');
